String uid() => DateTime.now().microsecondsSinceEpoch.toString();
String today() => DateTime.now().toIso8601String().substring(0, 10);

Future<void> main() async { WidgetsFlutterBinding.ensureInitialized(); runApp(const RentFlowApp()); }

class Store extends ChangeNotifier {
  late SharedPreferences prefs;
  List<Map<String,dynamic>> shops=[]; int active=0;
  bool get registered=>shops.isNotEmpty;
  Map<String,dynamic> get shop=>registered?shops[active]:<String,dynamic>{};
  List<Map<String,dynamic>> list(String key){final v=shop[key]; if(v is! List)return []; return v.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();}
  List<Map<String,dynamic>> get items=>list('items');
  List<Map<String,dynamic>> get customers=>list('customers');
  List<Map<String,dynamic>> get issued=>list('issued');
  List<Map<String,dynamic>> get returns=>list('returns');
  Future<void> load() async { prefs=await SharedPreferences.getInstance(); try{final r=jsonDecode(prefs.getString('shops')??'[]'); if(r is List)shops=r.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();}catch(_){shops=[];} active=prefs.getInt('active')??0; if(active>=shops.length)active=shops.isEmpty?0:shops.length-1; }
  Map<String,dynamic> makeShop(String n,String o,String m,String a)=>{'id':uid(),'name':n,'owner':o,'mobile':m,'address':a,'items':<Map<String,dynamic>>[],'customers':<Map<String,dynamic>>[],'issued':<Map<String,dynamic>>[],'returns':<Map<String,dynamic>>[]};
  Future<void> save() async {await prefs.setString('shops',jsonEncode(shops));await prefs.setInt('active',active);notifyListeners();}
  Future<void> addShop(String n,String o,String m,String a)async{shops.add(makeShop(n.trim(),o.trim(),m.trim(),a.trim()));active=shops.length-1;await save();}
  Future<void> updateShop(String n,String o,String m,String a)async{if(!registered)return;shop['name']=n.trim();shop['owner']=o.trim();shop['mobile']=m.trim();shop['address']=a.trim();await save();}
  Future<void> deleteShop(int i)async{if(i<0||i>=shops.length)return;shops.removeAt(i);active=shops.isEmpty?0:active.clamp(0,shops.length-1).toInt();await save();}
  Future<void> selectShop(int i)async{if(i<0||i>=shops.length)return;active=i;await save();}
  Future<void> add(String key,Map<String,dynamic> v)async{(shop[key] as List).add(v);await save();}
  Future<void> update(String key,int i,Map<String,dynamic> v)async{(shop[key] as List)[i]=v;await save();}
  Future<void> remove(String key,int i)async{(shop[key] as List).removeAt(i);await save();}
}

