class _ShopFormState extends State<ShopForm>{final n=TextEditingController(),o=TextEditingController(),m=TextEditingController(),a=TextEditingController();@override void initState(){super.initState();if(widget.index!=null){final x=widget.store.shops[widget.index!];n.text='${x['name']}';o.text='${x['owner']}';m.text='${x['mobile']}';a.text='${x['address']}';}}@override Widget build(BuildContext c)=>FormPage(title:widget.index==null?'New Shop':'Edit Shop',fields:[FieldBox(label:'Shop name',controller:n),FieldBox(label:'Owner name',controller:o),FieldBox(label:'Mobile',controller:m,number:true),FieldBox(label:'Shop address',controller:a,maxLines:3)],onSave:()async{if(n.text.trim().isEmpty)return;if(widget.index==null)await widget.store.addShop(n.text,o.text,m.text,a.text);else await widget.store.updateShop(n.text,o.text,m.text,a.text);if(c.mounted)Navigator.pop(c);});}

class SettingsPage extends StatelessWidget{final Store store;const SettingsPage({required this.store,super.key});Future<void>check(BuildContext c)async{showDialog(context:c,builder:(_)=>const AlertDialog(content:Row(children:[CircularProgressIndicator(color:primary),SizedBox(width:16),Text('Checking for updates...')])));try{final r=await http.get(Uri.parse('https://api.github.com/repos/shanpalia/RentFlow/releases/latest'),headers:{'Accept':'application/vnd.github+json'});if(c.mounted)Navigator.pop(c);if(!c.mounted)return;final data=r.statusCode==200?jsonDecode(r.body):{};final url='${data['html_url']??'https://github.com/shanpalia/RentFlow/releases'}';showDialog(context:c,builder:(_)=>AlertDialog(title:Text(r.statusCode==200?'Latest release found':'Update check'),content:Text(r.statusCode==200?'Open the latest RentFlow release to download the newest APK.':'No release information was returned.'),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Close')),if(r.statusCode==200)FilledButton(onPressed:()async{final u=Uri.parse(url);if(await canLaunchUrl(u))await launchUrl(u,mode:LaunchMode.externalApplication);},child:const Text('Open Release'))]));}catch(_){if(c.mounted){Navigator.pop(c);ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Could not check for updates.')));}}}@override Widget build(BuildContext c)=>Page(title:'Settings',child:Column(children:[Section(child:Column(children:[const ListTile(leading:Icon(Icons.storefront_outlined,color:primary),title:Text('Current shop'),subtitle:Text('Manage shop, address and owner details')),ListTile(leading:const Icon(Icons.swap_horiz,color:primary),title:const Text('Switch shop'),subtitle:Text('${store.shops.length} shop(s) registered'),onTap:()=>open(c,ShopManager(store:store))),const Divider(height:1),ListTile(leading:const Icon(Icons.system_update_alt,color:primary),title:const Text('Check for updates'),subtitle:const Text('Check the official RentFlow release'),trailing:const Icon(Icons.chevron_right),onTap:()=>check(c))])),const SizedBox(height:14),Section(child:const Column(children:[Text('RentFlow',style:TextStyle(color:dark,fontSize:18,fontWeight:FontWeight.w900)),SizedBox(height:3),Text('By PaliaAPK HUB',style:TextStyle(color:primary,fontWeight:FontWeight.w800)),Text('Developer by ShanPalia',style:TextStyle(color:Colors.black54,fontSize:12))]))]));}

